import org.jetbrains.kotlin.gradle.dsl.JvmTarget

plugins {
    alias(libs.plugins.kotlin.multiplatform)
    alias(libs.plugins.android.kmp.library)
    alias(libs.plugins.kotlin.compose)
    alias(libs.plugins.kotlin.serialization)
    alias(libs.plugins.sqldelight)
}

// The Kotlin bindings of the Rust core (core/), generated by uniffi-bindgen from a host build of
// the core, so they always match its code. The JVM host tests load that same host library.
val cargoTargetDir =
    providers
        .environmentVariable("CARGO_TARGET_DIR")
        .map { file(it) }
        .orElse(
            rootProject.layout.projectDirectory
                .dir("target")
                .asFile,
        )
val hostCoreLibrary =
    cargoTargetDir.map { dir ->
        val ext = if (System.getProperty("os.name").startsWith("Mac")) "dylib" else "so"
        File(dir, "debug/libpubky_maps_core.$ext")
    }
val coreBindingsDir = layout.buildDirectory.dir("generated/uniffi/kotlin")
val generateCoreBindings =
    tasks.register<Exec>("generateCoreBindings") {
        description = "Builds the Rust core for this machine and generates its Kotlin bindings."
        val root = rootProject.layout.projectDirectory
        inputs.files(
            root.file("Cargo.toml"),
            root.file("Cargo.lock"),
            root.dir("core/src").asFileTree,
            root.file("core/Cargo.toml"),
            root.file("core/uniffi.toml"),
            root.dir("core/uniffi-bindgen").asFileTree,
            root.file("scripts/gen-kotlin-bindings.sh"),
        )
        outputs.dir(coreBindingsDir)
        outputs.file(hostCoreLibrary)
        commandLine("bash", root.file("scripts/gen-kotlin-bindings.sh").asFile.path, coreBindingsDir.get().asFile.path)
    }

kotlin {
    android {
        namespace = "to.pubky.maps.shared"
        compileSdk =
            libs.versions.android.compileSdk
                .get()
                .toInt()
        minSdk =
            libs.versions.android.minSdk
                .get()
                .toInt()
        compilerOptions {
            jvmTarget.set(
                JvmTarget.fromTarget(
                    libs.versions.java.bytecode
                        .get(),
                ),
            )
        }
        withHostTest {}
    }

    // Declared so the shared code stays iOS-ready; these targets only build on macOS.
    listOf(iosArm64(), iosSimulatorArm64()).forEach { target ->
        target.binaries.framework {
            baseName = "Shared"
            isStatic = true
        }
    }

    sourceSets {
        commonMain.dependencies {
            implementation(libs.compose.runtime)
            implementation(libs.compose.foundation)
            implementation(libs.compose.ui)
            implementation(libs.compose.material3)
            implementation(libs.navigation.compose)
            implementation(libs.lifecycle.runtime.compose)
            implementation(libs.kotlinx.coroutines.core)
            implementation(libs.kotlinx.serialization.core)
            implementation(libs.kotlinx.serialization.json)
            implementation(libs.datastore.core.okio)
            api(libs.okio)
            implementation(libs.maplibre.compose)
            implementation(libs.maplibre.compose.location)
            // LicencesScreen takes a Libs.
            api(libs.aboutlibraries.core)
            implementation(libs.aboutlibraries.compose.m3)
            // AccountCache takes a SqlDriver.
            api(libs.sqldelight.runtime)
            implementation(libs.qrose)
        }
        androidMain {
            kotlin.srcDir(files(coreBindingsDir).builtBy(generateCoreBindings))
            dependencies {
                implementation("${libs.jna.get()}@aar")
                implementation(libs.androidx.annotation)
                implementation(libs.sqldelight.android.driver)
            }
        }
        commonTest.dependencies {
            implementation(kotlin("test"))
            implementation(libs.kotlinx.coroutines.test)
            implementation(libs.okio.fakefilesystem)
        }
        getByName("androidHostTest").dependencies {
            // JNA with its desktop native part, and SQLite over JDBC, for tests on this machine.
            implementation(libs.jna)
            implementation(libs.sqldelight.sqlite.driver)
        }
    }
}

sqldelight {
    databases {
        create("CacheDatabase") {
            packageName.set("to.pubky.maps.cache.db")
        }
    }
}

tasks.withType<Test>().configureEach {
    dependsOn(generateCoreBindings)
    systemProperty("uniffi.component.pubky_maps_core.libraryOverride", hostCoreLibrary.get().path)
}
